import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

public class BarracksTowerHandler
implements IPlacementHandler {
    public boolean canHandle(@NotNull Level world, @NotNull BlockPos pos, @NotNull BlockState blockState) {
        return blockState.m_60734_() == ModBlocks.blockHutBarracksTower;
    }

    public List<ItemStack> getRequiredItems(@NotNull Level world, @NotNull BlockPos pos, @NotNull BlockState blockState, @Nullable CompoundTag tileEntityData, @NotNull IPlacementContext placementContext) {
        return Collections.emptyList();
    }

    public IPlacementHandler.ActionProcessingResult handle(@NotNull Level world, @NotNull BlockPos pos, @NotNull BlockState blockState, @Nullable CompoundTag tileEntityData, @NotNull IPlacementContext placementContext) {
        if (!WorldUtil.setBlockState((LevelAccessor)world, pos, blockState, 3)) {
            return IPlacementHandler.ActionProcessingResult.PASS;
        }
        if (tileEntityData != null) {
            try {
                PlacementHandlers.handleTileEntityPlacement((CompoundTag)tileEntityData, (Level)world, (BlockPos)pos, (RotationMirror)placementContext.getRotationMirror().getRotationMirror());
                blockState.m_60734_().m_6402_(world, pos, blockState, null, BlockUtils.getItemStackFromBlockState((BlockState)blockState));
            }
            catch (Exception ex) {
                Log.getLogger().warn("Unable to place TileEntity");
            }
        }
        return IPlacementHandler.ActionProcessingResult.SUCCESS;
    }

    public boolean doesWorldStateMatchBlueprintState(BlockState blueprintState, BlockState worldState, Tuple<BlockEntity, CompoundTag> tuple, @NotNull IPlacementContext iPlacementContext) {
        return blueprintState.equals(worldState);
    }
}

